"""Validators over depot run outputs. Each subclasses ``Check`` and implements ``check(items)``.

``Check.run`` already fails empty input and a ``measured`` value that is empty, and turns any
exception raised here into a failed result. Each ``check`` therefore only decides pass/fail
and returns what it measured.
"""
from __future__ import annotations

from checks_base import Check, is_empty


def _is_int(value) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


class V1(Check):
    """Every report row's value matches units x cost."""

    name = "V1"

    def check(self, items):
        mismatches = []
        for row in items:
            for key in ("sku", "wh", "units", "value_cents", "unit_cost"):
                if key not in row:
                    raise ValueError(f"row missing {key!r}")
            if not isinstance(row["sku"], str) or not isinstance(row["wh"], str):
                raise ValueError("sku and wh must be str")
            if not all(_is_int(row[k]) for k in ("units", "value_cents", "unit_cost")):
                raise ValueError("units, value_cents and unit_cost must be int")
            if row["value_cents"] != row["units"] * row["unit_cost"]:
                mismatches.append((row["sku"], row["wh"]))
        measured = {"rows": len(items), "mismatches": mismatches}
        return (not mismatches), measured


class V2(Check):
    """All notification types in the spec were seen across a set of runs."""

    name = "V2"

    # Notification types named in the spec: OVERDRAWN (C20), REORDER (C14), EXPIRY (C13),
    # AUDIT_MISMATCH (C22), SUPPLIER_SUSPENDED (C17).
    EXPECTED_TYPES = frozenset(
        {"OVERDRAWN", "REORDER", "EXPIRY", "AUDIT_MISMATCH", "SUPPLIER_SUSPENDED"}
    )

    def check(self, items):
        seen = set()
        for run in items:
            for notification in run:
                kind = notification[0]
                if not isinstance(kind, str):
                    raise ValueError("notification type must be str")
                seen.add(kind)
        missing = sorted(self.EXPECTED_TYPES - seen)
        measured = {"seen": sorted(seen), "missing": missing}
        return (not missing), measured


class V3(Check):
    """Two runs with the same seed are identical."""

    name = "V3"

    def check(self, items):
        compared = []
        differing = []
        for pair in items:
            seed = pair["seed"]
            if not _is_int(seed):
                raise ValueError("seed must be int")
            a, b = pair["a"], pair["b"]
            # A pair with an empty run on either side says nothing about determinism,
            # so it is not counted as measured.
            if is_empty(a) or is_empty(b):
                continue
            compared.append(seed)
            if a != b:
                differing.append(seed)
        measured = {"compared_seeds": compared, "differing_seeds": differing}
        if not compared:
            return False, []  # nothing measured; run() reports this
        return (not differing), measured


class V4(Check):
    """Storage cost stayed within a budget on every day."""

    name = "V4"

    def check(self, items):
        checked = []
        over = []
        for day in items:
            d = day["day"]
            cost = day["storage_cost_cents"]
            budget = day["budget_cents"]
            if not all(_is_int(x) for x in (d, cost, budget)):
                raise ValueError("day, storage_cost_cents and budget_cents must be int")
            checked.append(d)
            if cost > budget:
                over.append({"day": d, "storage_cost_cents": cost, "budget_cents": budget})
        measured = {"checked_days": checked, "over_budget": over}
        return (not over), measured


class V5(Check):
    """Every clause has at least one test."""

    name = "V5"

    def check(self, items):
        covered = {}
        for entry in items:
            cid = entry["clause_id"]
            if not isinstance(cid, str):
                raise ValueError("clause_id must be str")
            tests = entry["tests"] or []
            has_test = any(isinstance(t, str) and t for t in tests)
            covered[cid] = covered.get(cid, False) or has_test
        untested = sorted(cid for cid, ok in covered.items() if not ok)
        measured = {"clauses": sorted(covered), "untested": untested}
        return (not untested), measured


class V6(Check):
    """Results from two implementations agree on every compared pair."""

    name = "V6"

    def check(self, items):
        compared = []
        disagreeing = []
        for pair in items:
            key = pair["key"]
            compared.append(key)
            if pair["a"] != pair["b"]:
                disagreeing.append(key)
        measured = {"compared_keys": compared, "disagreeing_keys": disagreeing}
        return (not disagreeing), measured
```

`checks_base.py`:

```
"""The ``Check`` base class: a check never passes on nothing (brief 3, and E2's guard condition).

``Check.run(items)`` returns ``failed: empty input`` for empty or all-unmeasured input *before*
calling the subclass, and ``failed: nothing measured`` when the subclass measured nothing. The
harness's own checks (presence, reach, parity, mutation) subclass it, and so do the agent's
validators in E2's guard condition (the agent gets this file as ``checks_base.py``).

This file is standard-library only so it can be copied verbatim into the agent's repo.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass
class CheckResult:
    passed: bool
    measured: Any
    reason: str = ""

    def __iter__(self):  # allows ``passed, measured = check.run(x)``
        yield self.passed
        yield self.measured

    def __bool__(self) -> bool:
        return bool(self.passed)


def is_empty(value: Any) -> bool:
    """True for None, empty containers, and containers whose every leaf is None or empty."""
    if value is None:
        return True
    if isinstance(value, (str, bytes)):
        return len(value) == 0
    if isinstance(value, dict):
        return len(value) == 0 or all(is_empty(v) for v in value.values())
    if isinstance(value, (list, tuple, set, frozenset)):
        return len(value) == 0 or all(is_empty(v) for v in value)
    return False


class Check:
    """Subclasses implement ``check(items) -> (passed, measured)``; callers use ``run(items)``."""

    name = "check"

    def run(self, items: Any) -> CheckResult:
        if hasattr(items, "__next__"):  # a lazy source of runs: materialise before judging emptiness
            items = list(items)
        if is_empty(items):
            return CheckResult(False, None, "failed: empty input")
        try:
            passed, measured = self.check(items)
        except Exception as exc:  # a check that crashes has not passed
            return CheckResult(False, None, f"failed: {type(exc).__name__}: {exc}")
        if is_empty(measured):
            return CheckResult(False, measured, "failed: nothing measured")
        return CheckResult(bool(passed), measured, "" if passed else "failed")

    def check(self, items: Any) -> tuple[bool, Any]:  # pragma: no cover - abstract
        raise NotImplementedError
```

